books = [{"title": "رحلة العلم", "available": True}]
def find_book(title):
    return next((book for book in books if book["title"].lower() == title.lower()), None)
def borrow(title):
    book = find_book(title)
    if book and book["available"]:
        book["available"] = False
        return "تمت الاستعارة"
    return "الكتاب غير متاح"
def return_book(title):
    book = find_book(title)
    if book:
        book["available"] = True
        return "تم الإرجاع"
    return "الكتاب غير موجود"

contacts = []
def add_contact(name, phone):
    name = name.strip()
    if not name or not phone.strip():
        return False
    if any(item["name"].lower() == name.lower() for item in contacts):
        return False
    contacts.append({"name": name, "phone": phone.strip()})
    return True
def find_contact(name):
    return next((item for item in contacts if item["name"].lower() == name.strip().lower()), None)

expenses = []
def add_expense(amount, category, note):
    if amount <= 0 or not category.strip():
        return False
    expenses.append({"amount": amount, "category": category.strip(), "note": note.strip()})
    return True
def total_for(category):
    return sum(item["amount"] for item in expenses if item["category"].lower() == category.lower())

