const clock = document.querySelector("#clock");
function updateClock() {
  const now = new Date();
  clock.textContent = [now.getHours(), now.getMinutes(), now.getSeconds()].map(value => String(value).padStart(2, "0")).join(":");
}
updateClock();
setInterval(updateClock, 1000);

const notes = JSON.parse(localStorage.getItem("efhama-notes") || "[]");
const list = document.querySelector("#notes");
function render() { list.textContent = ""; for (const text of notes) { const item = document.createElement("li"); item.textContent = text; list.appendChild(item); } }
document.querySelector("#save").addEventListener("click", async () => {
  const input = await document.querySelector("#note");
  if (!input.value.trim()) return;
  notes.push(input.value.trim());
  localStorage.setItem("efhama-notes", JSON.stringify(notes));
  input.value = "";
  render();
});
render();

