const lessons = [{ title: "المتغيرات", topic: "أساسيات" }, { title: "الشروط", topic: "أساسيات" }];
const root = document.querySelector("#lessons");
const filter = document.querySelector("#topic");
function render() {
  root.textContent = "";
  for (const lesson of lessons.filter(item => filter.value === "all" || item.topic === filter.value)) {
    const card = document.createElement("article");
    card.textContent = `${lesson.title} - ${lesson.topic}`;
    root.appendChild(card);
  }
}
filter.addEventListener("change", render);
render();
